<script lang="ts">
import {authenticatedFetch} from '../../lib/auth';
import {onMount,onDestroy} from 'svelte';
import {api} from '../../lib/api';
export let bookId:number;
type Asset={id:number;url:string;thumbnail_url?:string;width?:number;height?:number;thumbnail_width?:number;thumbnail_height?:number;source_kind:string;source_edition_id:string;selected:boolean};
type Edition={id:string;title:string;publisher:string;publication_date:string;isbn:string;format:string;languages:string[];has_cover:boolean};
type OwnedEdition={title:string;isbn:string;publisher:string;publication_date:string;edition_id:string};
let owned:OwnedEdition|null=null;let contributionReviewed=false;$: selectedAsset=assets.find(a=>a.selected);
let uploadFile:File|null=null;let uploadPreview='';onDestroy(()=>{if(uploadPreview)URL.revokeObjectURL(uploadPreview)});
let editions:Edition[]=[];let editionPage=1;let hasMore=false;let editionURL='';let assets:Asset[]=[];let busy=false;let error='';let message='';
onMount(()=>{api<{assets:Asset[];edition_url:string;owned_edition:OwnedEdition}>(`/api/books/${bookId}/covers`).then(v=>{assets=v.assets;editionURL=v.edition_url;owned=v.owned_edition}).catch(e=>error=e.message)});
async function change(action:string,body?:unknown){busy=true;error='';message='';try{const v=await api<{assets:Asset[];page_warning?:string}>(`/api/books/${bookId}/covers/${action}`,body??{});assets=v.assets;contributionReviewed=false;if(v.page_warning){message=v.page_warning}else{window.location.reload()}}catch(e){error=(e as Error).message}finally{busy=false}}
async function findCovers(){busy=true;error='';message='';try{const v=await api<{assets:Asset[]}>(`/api/books/${bookId}/covers/fetch`,{});assets=v.assets;message='Choose a cover below to save it. Your current cover stays unchanged until you choose.'}catch(e){error=(e as Error).message}finally{busy=false}}
function chooseUpload(e:Event){if(uploadPreview)URL.revokeObjectURL(uploadPreview);uploadPreview='';uploadFile=null;error='';const input=e.currentTarget as HTMLInputElement;const file=input.files?.[0];if(!file)return;if(file.size>8*1024*1024){error='Choose an image up to 8 MB';input.value='';return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){error='Choose a JPEG, PNG or WebP image';input.value='';return}uploadFile=file;uploadPreview=URL.createObjectURL(file)}
async function upload(){const file=uploadFile;if(!file)return;busy=true;error='';message='';try{const body=new FormData();body.append('image',file);const r=await authenticatedFetch(`/api/books/${bookId}/covers/upload`,{method:'POST',body});const v=await r.json();if(!r.ok)throw new Error(v.error||'Could not upload cover');assets=v.assets;contributionReviewed=false;if(uploadPreview)URL.revokeObjectURL(uploadPreview);uploadPreview='';uploadFile=null;if(v.page_warning){message=v.page_warning}else{window.location.reload()}}catch(e){error=(e as Error).message}finally{busy=false}}
async function browse(page=1){busy=true;error='';try{const v=await api<{editions:Edition[];has_more:boolean;page:number}>(`/api/books/${bookId}/covers/editions?page=${page}`);editions=v.editions;editionPage=v.page;hasMore=v.has_more;if(!editions.length)message='No other editions on this page.'}catch(e){error=(e as Error).message}finally{busy=false}}
async function preview(edition_id:string){busy=true;error='';try{const v=await api<{assets:Asset[]}>(`/api/books/${bookId}/covers/edition`,{edition_id});assets=v.assets;message='Covers cached below. Choose artwork to use it. Your book details stay the same.'}catch(e){error=(e as Error).message}finally{busy=false}}
</script>
<details class="cover-picker"><summary>Change cover</summary><div class="cover-picker_body"><p>Choose a cover for this edition, or upload a photo of your own book. Your choice is kept locally.</p><button class="library-button" disabled={busy} onclick={findCovers}>{busy?'Working…':'Find edition covers'}</button>{#if assets.length}<div class="cover-picker_grid">{#each assets as a}<button class="cover-picker_choice" aria-pressed={a.selected} disabled={busy||a.selected} onclick={()=>change('select',{asset_id:a.id})}><img src={a.thumbnail_url || a.url} width={a.thumbnail_width || undefined} height={a.thumbnail_height || undefined} onerror={(event)=>{const img=event.currentTarget as HTMLImageElement;if(img.src!==new URL(a.url,window.location.origin).href)img.src=a.url}} alt={a.source_kind==='upload'?'Your uploaded cover':`Open Library edition ${a.source_edition_id} cover`} loading="lazy"/><span>{a.selected?'Selected':a.source_kind==='upload'?'Your image':'Use this cover'}</span>{#if a.source_kind==='other-edition'}<small>Artwork from {a.source_edition_id}</small>{/if}</button>{/each}</div>{/if}<details><summary>Browse artwork from other editions</summary><p>Different editions may use different artwork. Choosing their cover keeps your book's ISBN and details.</p><button class="library-button" disabled={busy} onclick={()=>browse()}>Find other editions</button>{#if editions.length}<ul class="cover-picker_editions">{#each editions as edition}<li><strong>{edition.title || edition.id}</strong><small>{[edition.publisher,edition.publication_date,edition.format,edition.languages.join(', '),edition.isbn].filter(Boolean).join(' · ')}</small><button class="library-button" disabled={busy||!edition.has_cover} onclick={()=>preview(edition.id)}>{edition.has_cover?'Preview covers':'No cover listed'}</button></li>{/each}</ul>{/if}<div>{#if editionPage>1}<button class="library-button" disabled={busy} onclick={()=>browse(editionPage-1)}>Previous editions</button>{/if}{#if hasMore}<button class="library-button" disabled={busy} onclick={()=>browse(editionPage+1)}>More editions</button>{/if}</div></details><label class="library-field">Upload a cover<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onchange={chooseUpload}/><small>JPEG, PNG or WebP, up to 8 MB. Uploads are oriented, resized and stripped of camera metadata. They stay on this device.</small></label>{#if uploadPreview}<div class="cover-picker_upload"><img src={uploadPreview} alt="Preview of your selected cover"/><button class="library-button" disabled={busy} onclick={upload}>{busy?'Saving…':'Use this cover'}</button></div>{/if}{#if editionURL}<details class="cover-contribution"><summary>Contribute this cover to Open Library</summary><p>Review your saved edition before sharing its cover publicly. This library only prepares a download; you upload it yourself on Open Library.</p>{#if owned}<dl><dt>Title</dt><dd>{owned.title}</dd><dt>ISBN</dt><dd>{owned.isbn || 'No ISBN saved'}</dd><dt>Publisher and date</dt><dd>{[owned.publisher,owned.publication_date].filter(Boolean).join(' · ') || 'Not recorded'}</dd><dt>Open Library edition</dt><dd>{owned.edition_id}</dd></dl>{/if}{#if selectedAsset}{#if selectedAsset.source_kind==='other-edition'}<p class="library-error">This artwork came from {selectedAsset.source_edition_id}, another edition. Only contribute it to your saved edition if it matches the physical book you own.</p>{/if}<label class="cover-contribution_check"><input type="checkbox" bind:checked={contributionReviewed}/>I checked that this cover matches my book's edition and that the edition details above are correct.</label>{#if contributionReviewed}<a class="library-button" href={`/api/books/${bookId}/covers/${selectedAsset.id}/download`} download>Download cover without camera metadata</a>{:else}<button class="library-button" disabled>Review edition to download</button>{/if}<ol><li>Check the ISBN, publisher and publication date against your physical book.</li><li>Download the prepared cover above.</li><li><a href={editionURL} target="_blank" rel="noreferrer">Open the saved edition on Open Library</a>, check its details again, then use its cover-upload option while signed in.</li></ol><p>Your local cover, copies and lending records stay unchanged.</p>{:else}<p>Select a local cover first to prepare a download.</p><a href={editionURL} target="_blank" rel="noreferrer">Review the saved edition on Open Library</a>{/if}</details>{/if}{#if error}<p class="library-error" role="alert">{error}</p>{/if}{#if message}<p role="status">{message}</p>{/if}</div></details>
<style>@layer components {.cover-picker{margin-block:var(--space-4);summary{cursor:pointer;font-weight:600}.cover-picker_body{display:grid;gap:var(--space-3);padding-block:var(--space-3)}.cover-contribution_check{display:flex;align-items:start;gap:var(--space-2);input{width:1.2rem;flex-shrink:0;margin-top:.2rem}}.cover-contribution{display:grid;gap:var(--space-3);dl{display:grid;grid-template-columns:1fr 2fr;gap:var(--space-2)}dt{font-weight:600}ol{list-style:decimal;padding-inline-start:var(--space-4)}}.cover-picker_upload{display:grid;gap:var(--space-3);img{max-height:20rem;max-width:100%;object-fit:contain}}.cover-picker_editions{display:grid;gap:var(--space-3);li{display:grid;gap:var(--space-2);border-bottom:var(--border-width) solid var(--border);padding-block:var(--space-3)}}.cover-picker_grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(8rem,1fr));gap:var(--space-3)}.cover-picker_choice{display:grid;gap:var(--space-2);padding:var(--space-2);border:var(--border-width) solid var(--border);border-radius:var(--radius-small);background:var(--background-3);cursor:pointer;img{height:12rem;width:100%;object-fit:contain} &[aria-pressed=true]{outline:.15rem solid var(--brand-500)} &:disabled{opacity:1;cursor:default}}}}</style>
